import{_ as e,o as a,c as i,a4 as n}from"./chunks/framework.BAxM5-cj.js";const u=JSON.parse('{"title":"Sprint 13 — Client Portal, Analytics & Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"plan/sprints/Sprint_13_Client_Portal_Analytics_Notifications.md","filePath":"plan/sprints/Sprint_13_Client_Portal_Analytics_Notifications.md"}'),o={name:"plan/sprints/Sprint_13_Client_Portal_Analytics_Notifications.md"};function r(l,t,d,s,c,p){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="sprint-13-—-client-portal-analytics-notifications" tabindex="-1">Sprint 13 — Client Portal, Analytics &amp; Notifications <a class="header-anchor" href="#sprint-13-—-client-portal-analytics-notifications" aria-label="Permalink to &quot;Sprint 13 — Client Portal, Analytics &amp; Notifications&quot;">​</a></h1><p><strong>Timeline:</strong> Weeks 25–26 (Nov 4–17, 2026) <strong>Jira:</strong> DA Sprint 13 <strong>Phase:</strong> Phase 6 — Frontend &amp; Analytics <strong>Goal:</strong> Build the isolated Brand Client portal, analytics dashboard with charts, automated report generation, and the notification center.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Title</th><th>Owner</th></tr></thead><tbody><tr><td>E37</td><td>Client Portal</td><td>Lộc</td></tr><tr><td>E38</td><td>Analytics &amp; Reporting</td><td>Trung, Ân, Lộc</td></tr><tr><td>E39</td><td>Notification System</td><td>Trung, Lộc</td></tr></tbody></table><p><strong>Deliverables by end of Sprint 13:</strong></p><ul><li>Brand Client can log in to an isolated portal (only sees own data)</li><li>Client can view calendar, approve/reject posts</li><li>Analytics Dashboard with charts (success rate, platform breakdown, campaign performance)</li><li>Automated weekly/monthly PDF reports emailed to clients</li><li>Notification center: bell icon, unread badge, mark as read</li></ul><hr><h2 id="epic-e37-—-client-portal" tabindex="-1">EPIC E37 — Client Portal <a class="header-anchor" href="#epic-e37-—-client-portal" aria-label="Permalink to &quot;EPIC E37 — Client Portal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E37-01</td><td>Build Client Portal login (isolated, only shows data for the logged-in client)</td><td>Lộc (Frontend)</td><td>🔴 Critical</td></tr><tr><td>DA-E37-02</td><td>Build Client Calendar (read-only, view only, no editing)</td><td>Lộc (Frontend)</td><td>🔴 Critical</td></tr><tr><td>DA-E37-03</td><td>Build Client Approval page (view preview → approve/reject with feedback)</td><td>Lộc (Frontend)</td><td>🔴 Critical</td></tr><tr><td>DA-E37-04</td><td>Build Client Analytics page (publishing results, success rate, campaign summary)</td><td>Lộc (Frontend)</td><td>🟡 High</td></tr></tbody></table><p><strong>Client isolation (DA-E37-01):</strong></p><ul><li>BRAND_CLIENT role enforced by RBAC (Sprint 5)</li><li>All API calls include <code>clientId</code> filter at backend</li><li>Client cannot navigate to <code>/workspace</code>, <code>/clients</code>, or <code>/content</code> pages</li><li>Separate route prefix: <code>/portal/*</code></li></ul><p><strong>Client Approval page (DA-E37-03):</strong></p><ul><li>Shows posts in SENT_TO_CLIENT status</li><li>For each post: platform preview, caption, hashtags, scheduled date</li><li>&quot;Approve&quot; button → <code>POST /api/v1/posts/{id}/client-approve</code></li><li>&quot;Request Changes&quot; button → textarea for feedback → <code>POST /api/v1/posts/{id}/client-reject</code></li></ul><hr><h2 id="epic-e38-—-analytics-reporting" tabindex="-1">EPIC E38 — Analytics &amp; Reporting <a class="header-anchor" href="#epic-e38-—-analytics-reporting" aria-label="Permalink to &quot;EPIC E38 — Analytics &amp; Reporting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E38-01</td><td>Implement analytics aggregation APIs (aggregate data from posts + publish_logs)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E38-02</td><td>Implement automated report generation (weekly/monthly PDF report for clients)</td><td>Trung (Leader)</td><td>🟡 High</td></tr><tr><td>DA-E38-03</td><td>Implement report email sending (automatically send email to Brand Client on schedule)</td><td>Ân (AI)</td><td>🟡 High</td></tr><tr><td>DA-E38-04</td><td>Build Analytics Dashboard (charts: publishing success rate, platform breakdown, campaign performance)</td><td>Lộc (Frontend)</td><td>🔴 Critical</td></tr></tbody></table><p><strong>Analytics API endpoints (DA-E38-01):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/analytics/overview?clientId=&amp;period=30d</span></span>
<span class="line"><span>Response: {totalPosts, publishedPosts, failedPosts, successRate, postsByPlatform{}, postsByStatus{}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET /api/v1/analytics/timeline?clientId=&amp;startDate=&amp;endDate=&amp;groupBy=day</span></span>
<span class="line"><span>Response: [{date, published, failed, pending}]</span></span></code></pre></div><p><strong>PDF report (DA-E38-02):</strong></p><ul><li>Use <code>iTextPDF</code> (Java) or <code>jasperreports</code> library</li><li>Contents: cover page, summary stats, posts table, platform breakdown chart</li><li>Stored in S3 at <code>reports/{workspaceId}/{clientId}/{year}-{month}.pdf</code></li><li>Schedule: weekly (Monday 8:00 AM) and monthly (1st of month 8:00 AM)</li></ul><p><strong>Charts (DA-E38-04):</strong></p><ul><li>Use <code>Recharts</code> library</li><li>Line chart: posts published per day (30-day view)</li><li>Pie chart: breakdown by platform</li><li>Bar chart: success rate per platform</li><li>KPI cards: total posts, success rate %, avg time to publish</li></ul><hr><h2 id="epic-e39-—-notification-system" tabindex="-1">EPIC E39 — Notification System <a class="header-anchor" href="#epic-e39-—-notification-system" aria-label="Permalink to &quot;EPIC E39 — Notification System&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task ID</th><th>Description</th><th>Assignee</th><th>Priority</th></tr></thead><tbody><tr><td>DA-E39-01</td><td>Implement notification CRUD APIs (/api/v1/notifications: GET, PUT read, PUT read-all)</td><td>Trung (Leader)</td><td>🟡 High</td></tr><tr><td>DA-E39-02</td><td>Implement notification creation when events occur (post published, task assigned, token expiry, etc.)</td><td>Trung (Leader)</td><td>🔴 Critical</td></tr><tr><td>DA-E39-03</td><td>Build Notification Center UI (dropdown bell icon, unread badge, list with mark as read)</td><td>Lộc (Frontend)</td><td>🟡 High</td></tr></tbody></table><p><strong>Notification types (DA-E39-02):</strong></p><table tabindex="0"><thead><tr><th>Event</th><th>Recipient</th><th>Message</th></tr></thead><tbody><tr><td>Post published</td><td>CONTENT_CREATOR, ACCOUNT_MANAGER</td><td>&quot;Post &#39;{title}&#39; published on {platform}&quot;</td></tr><tr><td>Post failed</td><td>ACCOUNT_MANAGER</td><td>&quot;Post &#39;{title}&#39; failed to publish on {platform}&quot;</td></tr><tr><td>Task assigned</td><td>CONTENT_CREATOR</td><td>&quot;New task assigned: {topic}&quot;</td></tr><tr><td>Post submitted for review</td><td>ACCOUNT_MANAGER</td><td>&quot;&#39;{title}&#39; is ready for review&quot;</td></tr><tr><td>Post sent to client</td><td>BRAND_CLIENT</td><td>&quot;&#39;{title}&#39; is awaiting your approval&quot;</td></tr><tr><td>Token expiring in 3 days</td><td>ACCOUNT_MANAGER</td><td>&quot;{platform} token expiring in 3 days&quot;</td></tr><tr><td>Deadline in 24h</td><td>CONTENT_CREATOR</td><td>&quot;Task &#39;{topic}&#39; deadline in 24 hours&quot;</td></tr></tbody></table><p><strong>Notification Center UI (DA-E39-03):</strong></p><ul><li>Bell icon in Navbar with red badge showing unread count</li><li>Dropdown: list of last 20 notifications, newest first</li><li>Click notification → navigate to relevant page + mark as read</li><li>&quot;Mark all as read&quot; button</li></ul><hr><h2 id="sprint-13-checklist" tabindex="-1">Sprint 13 Checklist <a class="header-anchor" href="#sprint-13-checklist" aria-label="Permalink to &quot;Sprint 13 Checklist&quot;">​</a></h2><ul><li>[ ] BRAND_CLIENT logs in, sees only own client data</li><li>[ ] Client Calendar shows posts in read-only view</li><li>[ ] Client can approve a post → post status changes to SCHEDULED</li><li>[ ] Client can reject a post with feedback → status returns to DRAFT</li><li>[ ] Analytics overview API returns correct aggregated data</li><li>[ ] PDF report generated for a client (check S3 file exists)</li><li>[ ] Report email sent to Brand Client on schedule</li><li>[ ] Analytics Dashboard: all 4 chart types render with real data</li><li>[ ] Notification created on task assign, post status change, token expiry</li><li>[ ] Bell icon shows unread count</li><li>[ ] Dropdown shows last 20 notifications</li><li>[ ] Click notification → navigate to correct page + mark as read</li><li>[ ] Mark all as read: badge resets to 0</li></ul>`,33)])])}const g=e(o,[["render",r]]);export{u as __pageData,g as default};
